<?php
/**
 * Plugin Name: SMM Desk List
 * Description: Receives the list from the app and prints it with [smm_list].
 * Version: 1.9.1
 */

if (!defined('ABSPATH')) {
    exit;
}

add_action('rest_api_init', function () {
    register_rest_route('smm-desk/v1', '/list', array(
        'methods' => array('GET', 'POST'),
        'permission_callback' => 'smm_desk_list_allowed',
        'callback' => 'smm_desk_list_receive',
    ));
});

function smm_desk_list_token($request) {
    $header = (string) $request->get_header('authorization');
    $token = trim((string) preg_replace('/^Bearer\s+/i', '', $header));
    if ($token === '') {
        $token = trim((string) $request->get_header('x-smm-secret'));
    }
    if ($token === '') {
        $token = trim((string) $request->get_param('secret'));
    }
    if ($token === '') {
        $body = $request->get_json_params();
        if (is_array($body) && isset($body['secret'])) {
            $token = trim((string) $body['secret']);
        }
    }
    return preg_match('/^[A-Za-z0-9]{8,80}$/', $token) ? $token : '';
}

function smm_desk_list_allowed($request) {
    $secret = (string) get_option('smm_desk_secret', '');
    $token = smm_desk_list_token($request);
    if ($secret === '' && $token !== '') {
        update_option('smm_desk_secret', $token, false);
        return true;
    }
    if ($secret === '' || $token === '' || strlen($secret) !== strlen($token)) {
        return new WP_Error('smm_desk_denied', 'Secret does not match', array('status' => 401));
    }
    if (!hash_equals($secret, $token)) {
        return new WP_Error('smm_desk_denied', 'Secret does not match', array('status' => 401));
    }
    return true;
}

function smm_desk_list_store($body) {
    $incoming = is_array($body) && isset($body['updatedAt']) ? (int) $body['updatedAt'] : 0;
    $have = (int) get_option('smm_desk_updated_at', 0);
    if ($incoming > 0 && $have > 0 && $incoming < $have) {
        return count((array) get_option('smm_desk_items', array()));
    }
    $extra = null;
    if (is_array($body) && array_key_exists('badges', $body)) {
        $extra = smm_desk_badges_clean($body['badges']);
    }
    $items = array();
    if (is_array($body) && isset($body['items']) && is_array($body['items'])) {
        foreach ($body['items'] as $row) {
            if (!is_array($row)) {
                continue;
            }
            $title = sanitize_text_field($row['title'] ?? '');
            if ($title === '') {
                continue;
            }
            $items[] = array(
                'id' => sanitize_key($row['id'] ?? ''),
                'title' => $title,
                'url' => esc_url_raw($row['url'] ?? ''),
                'image' => smm_desk_image($row['image'] ?? ''),
                'badge' => smm_desk_badge_id($row['badge'] ?? '', $extra),
                'published' => true,
                'children' => smm_desk_list_children($row['children'] ?? array(), $extra),
            );
        }
    }
    $style = smm_desk_list_style(is_array($body) ? ($body['style'] ?? array()) : array());
    update_option('smm_desk_items', $items, false);
    update_option('smm_desk_style', $style, false);
    if ($extra !== null) {
        update_option('smm_desk_badges', $extra, false);
    }
    update_option('smm_desk_updated', time(), false);
    if ($incoming > 0) {
        update_option('smm_desk_updated_at', $incoming, false);
    }
    return count($items);
}

function smm_desk_list_receive($request) {
    if ($request->get_method() === 'GET') {
        $items = get_option('smm_desk_items', array());
        return array(
            'ok' => true,
            'updatedAt' => (int) get_option('smm_desk_updated_at', 0),
            'count' => is_array($items) ? count($items) : 0,
        );
    }
    $count = smm_desk_list_store($request->get_json_params());
    return array('ok' => true, 'count' => $count, 'updatedAt' => (int) get_option('smm_desk_updated_at', 0));
}

function smm_desk_list_pull() {
    $app = trim((string) get_option('smm_desk_app', ''));
    $secret = (string) get_option('smm_desk_secret', '');
    if ($app === '' || $secret === '') {
        return;
    }
    $url = rtrim($app, '/') . '/api/wp-list';
    $res = wp_remote_get($url, array(
        'timeout' => 4,
        'headers' => array('Authorization' => 'Bearer ' . $secret),
    ));
    if (is_wp_error($res) || (int) wp_remote_retrieve_response_code($res) !== 200) {
        return;
    }
    $body = json_decode(wp_remote_retrieve_body($res), true);
    if (!is_array($body)) {
        return;
    }
    smm_desk_list_store($body);
}

add_action('init', function () {
    if (get_transient('smm_desk_pull')) {
        return;
    }
    set_transient('smm_desk_pull', '1', 2 * MINUTE_IN_SECONDS);
    smm_desk_list_pull();
});

function smm_desk_list_style($raw) {
    $pick = function ($key, $allowed, $fallback) use ($raw) {
        $value = is_array($raw) && isset($raw[$key]) ? (string) $raw[$key] : '';
        return in_array($value, $allowed, true) ? $value : $fallback;
    };
    return array(
        'look' => $pick('look', array('soft', 'glass', 'outline', 'solid', 'neon', 'pill'), 'soft'),
        'tone' => $pick('tone', array('ink', 'paper', 'blue', 'gold', 'rose', 'mint'), 'blue'),
        'size' => $pick('size', array('sm', 'md', 'lg'), 'md'),
        'layout' => $pick('layout', array('stack', 'row', 'grid'), 'stack'),
        'thumb' => $pick('thumb', array('off', 'left', 'top'), 'left'),
        'badge' => $pick('badge', array('off', 'corner', 'inline'), 'corner'),
    );
}

function smm_desk_list_children($raw, $extra = null) {
    $out = array();
    if (!is_array($raw)) {
        return $out;
    }
    foreach ($raw as $row) {
        if (!is_array($row)) {
            continue;
        }
        $title = sanitize_text_field($row['title'] ?? '');
        if ($title === '') {
            continue;
        }
        $out[] = array(
            'title' => $title,
            'url' => esc_url_raw($row['url'] ?? ''),
            'image' => smm_desk_image($row['image'] ?? ''),
            'badge' => smm_desk_badge_id($row['badge'] ?? '', $extra),
        );
        if (count($out) >= 40) {
            break;
        }
    }
    return $out;
}

function smm_desk_image($raw) {
    $raw = trim((string) $raw);
    if (preg_match('#^https?://#i', $raw)) {
        return esc_url_raw($raw);
    }
    if (preg_match('#^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$#', $raw) && strlen($raw) <= 120000) {
        return $raw;
    }
    return '';
}

function smm_desk_hex($raw) {
    $raw = strtolower(trim((string) $raw));
    if (preg_match('/^#([0-9a-f]{6})$/', $raw)) {
        return $raw;
    }
    if (preg_match('/^#([0-9a-f]{3})$/', $raw, $m)) {
        $c = $m[1];
        return '#' . $c[0] . $c[0] . $c[1] . $c[1] . $c[2] . $c[2];
    }
    return '#111111';
}

function smm_desk_safe_path($raw) {
    $path = trim((string) $raw);
    if (strlen($path) < 2 || strlen($path) > 5000) {
        return '';
    }
    return preg_match('/^[MmLlHhVvCcSsQqTtAaZz0-9eE.,\\-\\s]+$/', $path) ? $path : '';
}

function smm_desk_badge_img($raw) {
    $raw = trim((string) $raw);
    if (preg_match('#^https?://#i', $raw)) {
        return esc_url_raw($raw);
    }
    if (preg_match('#^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$#', $raw) && strlen($raw) <= 80000) {
        return $raw;
    }
    if (preg_match('#^data:image/svg\\+xml;base64,[A-Za-z0-9+/=]+$#', $raw) && strlen($raw) <= 80000) {
        $bin = base64_decode(substr($raw, 26), true);
        if ($bin === false) {
            return '';
        }
        $low = strtolower($bin);
        if (strpos($low, '<svg') === false) {
            return '';
        }
        foreach (array('<script', 'foreignobject', 'onload', 'onerror', 'javascript:', '<iframe', '<embed', '<object') as $bad) {
            if (strpos($low, $bad) !== false) {
                return '';
            }
        }
        return $raw;
    }
    return '';
}

function smm_desk_badges_clean($raw) {
    $out = array();
    if (!is_array($raw)) {
        return $out;
    }
    foreach ($raw as $row) {
        if (!is_array($row)) {
            continue;
        }
        $id = sanitize_key($row['id'] ?? '');
        if (!preg_match('/^[a-z0-9][a-z0-9-]{1,39}$/', $id)) {
            continue;
        }
        $img = smm_desk_badge_img($row['img'] ?? '');
        $path = smm_desk_safe_path($row['path'] ?? '');
        if ($img === '' && $path === '') {
            continue;
        }
        $out[$id] = array(
            'label' => sanitize_text_field($row['label'] ?? ''),
            'bg' => smm_desk_hex($row['bg'] ?? ''),
            'fg' => smm_desk_hex($row['fg'] ?? '#ffffff'),
            'img' => $img,
            'path' => $path,
        );
        if (count($out) >= 80) {
            break;
        }
    }
    return $out;
}

function smm_desk_custom_map() {
    $raw = get_option('smm_desk_badges', array());
    return is_array($raw) ? $raw : array();
}

function smm_desk_badge_id($raw, $extra = null) {
    $id = sanitize_key((string) $raw);
    $known = is_array($extra) ? $extra : smm_desk_custom_map();
    if ($id !== '' && isset($known[$id])) {
        return $id;
    }
    $ok = array('star', 'heart', 'fire', 'bolt', 'play', 'music', 'shop', 'pin', 'crown', 'camera', 'gift', 'check', 'home', 'bell', 'spark', 'ticket', 'dress', 'heel', 'lips', 'bag', 'shades', 'bow', 'gem', 'hanger', 'bloom', 'scent', 'ring', 'hat', 'amazon', 'tiktokshop', 'ebay', 'walmart', 'target', 'etsy', 'shein', 'temu', 'aliexpress', 'shopify', 'nike', 'adidas', 'sephora', 'ulta', 'nordstrom', 'macys', 'ikea', 'hm', 'zara', 'gap', 'bestbuy', 'costco', 'homedepot', 'lowes', 'wayfair', 'chewy', 'depop', 'poshmark', 'mercari', 'stockx', 'google', 'apple', 'youtube', 'instagram', 'facebook', 'x', 'pinterest', 'netflix', 'spotify', 'paypal', 'discord', 'reddit', 'twitch', 'linkedin', 'whatsapp', 'snapchat', 'airbnb', 'uber', 'doordash', 'starbucks', 'yelp', 'booking', 'coach', 'guess', 'gucci', 'chanel', 'prada', 'louisvuitton', 'burberry', 'calvinklein', 'levis', 'converse', 'saintlaurent', 'fendi', 'dior', 'boss', 'katespade', 'americaneagle', 'abercrombie', 'vans', 'newbalance', 'skechers', 'uniqlo', 'thenorthface', 'asos', 'puma', 'underarmour', 'fila', 'reebok');
    if (in_array($id, $ok, true)) {
        return $id;
    }
    return '';
}

