        'thenorthface' => array('#111111', 'data:image/svg+xml;base64,'),
        'asos' => array('#ffffff', 'data:image/svg+xml;base64,'),
    );
    if (isset($logo_imgs[$id])) {
        $img = $logo_imgs[$id];
        return '<span class="smm-desk-badge" style="background:' . esc_attr($img[0]) . '"><img class="smm-desk-logo" alt="" src="' . esc_attr($img[1]) . '" /></span>';
    }
    if (isset($logo_paths[$id])) {
        $logo = $logo_paths[$id];
        return '<span class="smm-desk-badge" style="background:' . esc_attr($logo[0]) . ';color:' . esc_attr($logo[1]) . '"><svg viewBox="0 0 24 24" width="78%" height="78%" fill="' . esc_attr($logo[1]) . '" stroke="none"><path d="' . esc_attr($logo[2]) . '"></path></svg></span>';
    }
    if (!isset($marks[$id])) {
        return '';
    }
    $mark = $marks[$id];
    $fill = $mark[2] === '1' ? esc_attr($mark[1]) : 'none';
    $stroke = $mark[2] === '1' ? 'none' : esc_attr($mark[1]);
    return '<span class="smm-desk-badge" style="background:' . esc_attr($mark[0]) . ';color:' . esc_attr($mark[1]) . '"><svg viewBox="0 0 24 24" width="58%" height="58%" fill="' . $fill . '" stroke="' . $stroke . '" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="' . esc_attr($mark[3]) . '"></path></svg></span>';
}

function smm_desk_list_row($row) {
    $mark = '';
    $src = smm_desk_image($row['image'] ?? '');
    if ($src !== '') {
        $mark = '<img class="smm-desk-thumb" src="' . esc_attr($src) . '" alt="">';
    } else {
        $mark = smm_desk_badge_svg(smm_desk_badge_id($row['badge'] ?? ''));
    }
    $inner = $mark . '<span class="smm-desk-title">' . esc_html($row['title']) . '</span>';
    if (!empty($row['url'])) {
        return '<a class="smm-desk-btn btn" href="' . esc_url($row['url']) . '" target="_blank" rel="noopener noreferrer">' . $inner . '</a>';
    }
    return '<div class="smm-desk-btn btn">' . $inner . '</div>';
}

add_shortcode('smm_list', function () {
    $items = get_option('smm_desk_items', array());
    if (!is_array($items) || !$items) {
        return '';
    }
    $style = smm_desk_list_style(get_option('smm_desk_style', array()));
    $html = '<div class="smm-desk" data-look="' . esc_attr($style['look']) . '" data-tone="' . esc_attr($style['tone']) . '" data-size="' . esc_attr($style['size']) . '" data-layout="' . esc_attr($style['layout']) . '" data-thumb="' . esc_attr($style['thumb']) . '" data-badge="' . esc_attr($style['badge']) . '">';
    foreach ($items as $row) {
        $html .= '<div class="smm-desk-block">' . smm_desk_list_row($row);
        if (!empty($row['children']) && is_array($row['children'])) {
            $html .= '<div class="smm-desk-sub">';
            foreach ($row['children'] as $child) {
                $html .= smm_desk_list_row($child);
            }
            $html .= '</div>';
        }
        $html .= '</div>';
    }
    $html .= '</div>';
    $html .= '<style>' . smm_desk_list_css() . '</style>';
    return $html;
});

function smm_desk_list_css() {
    return '.smm-desk{--smm-thumb:36px;display:flex;flex-direction:column;gap:12px;max-width:640px;margin:0 auto}'
        . '.smm-desk[data-layout="row"]{flex-direction:row;flex-wrap:wrap}.smm-desk[data-layout="grid"]{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr))}'
        . '.smm-desk[data-size="sm"]{--smm-thumb:28px}.smm-desk[data-size="lg"]{--smm-thumb:48px}'
        . '.smm-desk .smm-desk-btn.btn{position:relative;display:flex;align-items:center;justify-content:center;gap:12px;width:100%;box-sizing:border-box;overflow:hidden;text-decoration:none;text-align:center;text-transform:none;letter-spacing:0;font-weight:700;font-size:22px;line-height:1.25;padding:18px 22px;color:#5c534c;background:#f6efe6;border:1.5px solid #6a615a;border-radius:12px;box-shadow:none;transition:transform .25s ease,box-shadow .25s ease,background .25s ease}'
        . '@media (hover:hover){.smm-desk .smm-desk-btn.btn:hover{transform:translateY(-3px);background:#efe4d6;color:#5c534c;box-shadow:0 8px 18px rgba(92,83,76,.16)}}'
        . '.smm-desk-thumb{width:var(--smm-thumb);height:var(--smm-thumb);border-radius:999px;object-fit:cover;flex:none}'
        . '.smm-desk-badge{width:var(--smm-thumb);height:var(--smm-thumb);margin:0;display:inline-flex;align-items:center;justify-content:center;padding:0;border-radius:999px;position:relative;overflow:hidden;flex:none;font-size:0;letter-spacing:0;text-transform:none;box-shadow:0 1px 1px rgba(0,0,0,.22),0 5px 10px rgba(0,0,0,.16),0 12px 20px rgba(0,0,0,.08),inset 0 1px 0 rgba(255,255,255,.78),inset 0 -2px 4px rgba(0,0,0,.12)}'
        . '.smm-desk-badge::after{content:"";position:absolute;top:6%;left:16%;width:68%;height:38%;border-radius:999px;background:linear-gradient(180deg,rgba(255,255,255,.55),transparent);pointer-events:none}'
        . '.smm-desk .smm-desk-badge svg,.smm-desk .smm-desk-mark{position:relative;z-index:1}'
        . '.smm-desk .smm-desk-mark{font:800 11px/1 system-ui,sans-serif;letter-spacing:-0.04em}'
        . '.smm-desk .smm-desk-badge .smm-desk-logo,.smm-desk .smm-desk-badge svg{position:relative;z-index:1;width:78%!important;height:78%!important;max-width:none!important;max-height:none!important;min-width:0;object-fit:contain;display:block!important}'
        . '.smm-desk-title{min-width:0;width:100%;white-space:normal;text-align:center;font-weight:700;letter-spacing:0;text-transform:none}'
        . '.smm-desk-block{display:flex;flex-direction:column;gap:8px;min-width:0}'
        . '.smm-desk-sub{display:flex;flex-direction:column;gap:8px;margin-left:18px}'
        . '.smm-desk-sub .smm-desk-btn.btn{font-size:18px;padding:14px 18px}';
}

