function smm_desk_list_settings() {
    if (!current_user_can('manage_options')) {
        return;
    }
    if (isset($_POST['smm_desk_secret']) && check_admin_referer('smm_desk_list')) {
        update_option('smm_desk_secret', sanitize_text_field(wp_unslash($_POST['smm_desk_secret'])));
        update_option('smm_desk_app', esc_url_raw(wp_unslash($_POST['smm_desk_app'] ?? '')));
        delete_transient('smm_desk_pull');
        echo '<div class="updated"><p>Saved.</p></div>';
    }
    $secret = esc_attr(get_option('smm_desk_secret', ''));
    $app = esc_attr(get_option('smm_desk_app', ''));
    $hook = esc_html(rest_url('smm-desk/v1/list'));
    echo '<div class="wrap"><h1>SMM Desk List</h1>';
    echo '<p>The app password stays on the app. This site uses the secret only, so the public page can stay up to date.</p>';
    echo '<p>Webhook address to paste in the app:</p><p><code>' . $hook . '</code></p>';
    echo '<p>Put <code>[smm_list]</code> on the page that should show the list.</p>';
    echo '<form method="post">';
    wp_nonce_field('smm_desk_list');
    echo '<p><label>App address<br><input name="smm_desk_app" value="' . $app . '" class="regular-text" placeholder="https://your-app.example" autocomplete="off"></label></p>';
    echo '<p><label>Secret<br><input name="smm_desk_secret" value="' . $secret . '" class="regular-text" autocomplete="off"></label></p>';
    submit_button();
    echo '</form></div>';
}
